export class Service { constructor(){} }
export class Context {}

/**
 * `symbols` —— 迷你模块（stub），只为了**让从 DSH 现取的那份 dsh-tools 能被 import**。
 *
 * ★ 2026-10-21 补：新版 DSH（0.2.x）的 dsh-tools 里有一行
 *     `import { Service, symbols } from "@deepseek-ai/cordis"`
 *   并用 `provider[symbols.original]` 顺着"被包装的原始 provider"往上爬。
 *   原来这个 stub 只导出 `Service`，于是自测在**最新版 DSH** 上会报
 *     `does not provide an export named 'symbols'`
 *   → 连带 4 条 schema 校验断言一起红（一共 5 条）。
 *   这不是插件坏了，是 stub 落后于 DSH 了。
 *
 * ⚠️ 这里只需要"是个 Symbol、且唯一"就够：自测只走到 `assertSupportedJsonSchema`，
 *    不会真的顺着包装链爬（真跑的时候 stub 的 Service 是空的，爬一步就 `undefined` 退出）。
 *    所以**别**在这里假装实现 cordis 的语义 —— 只要符号存在即可。
 */
export const symbols = {
  original: Symbol.for('cordis.original')
};

export default { Service, symbols };

